from typing import Iterable
def defeat_caps(caps: Iterable[int]) -> list[tuple[int, int]]:
    if any(c < 0 for c in caps): raise ValueError("caps must be nonnegative")
    return [(c, c + 1) for c in caps]
if __name__ == "__main__": print(defeat_caps([7, 19, 100]))

from __future__ import annotations
from dataclasses import dataclass
@dataclass(frozen=True, order=True)
class OrdinalPair:
    blocks: int
    tail: int
    def __post_init__(self) -> None:
        if self.blocks < 0 or self.tail < 0: raise ValueError("nonnegative coordinates required")
    def __str__(self) -> str:
        h = "0" if self.blocks == 0 else ("omega" if self.blocks == 1 else f"omega*{self.blocks}")
        return str(self.tail) if self.blocks == 0 else (h if self.tail == 0 else f"{h}+{self.tail}")

def window(K: int, N: int) -> list[OrdinalPair]:
    return [OrdinalPair(k,n) for k in range(K) for n in range(N)]
if __name__ == "__main__":
    print(*(str(x) for x in window(3,6)), sep="\n")

from fractions import Fraction
def dyadic_table(N: int) -> list[tuple[Fraction,int,str]]:
    return [(Fraction(1,2**n), n+1, f"omega*{n+1}") for n in range(N)]
if __name__ == "__main__":
    for row in dyadic_table(10): print(row)

